<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\PlatformIdentity\Application\Usecase\Update;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\PlatformIdentityRef;
use Civi\Lughauth\Features\Access\PlatformIdentity\Application\Service\Visibility\PlatformIdentityVisibilityService;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\Gateway\PlatformIdentityWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class PlatformIdentityUpdateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly PlatformIdentityVisibilityService $visibility,
        private readonly PlatformIdentityWriteGateway $writer,
    ) {
    }

    public function allowUpdate(?PlatformIdentityRef $ref = null): Allow
    {
        $this->logDebug("Check allow update usecase for Platform identity");
        $span = $this->startSpan("Check allow update usecase for Platform identity");
        try {
            $result = $this->dispatcher->dispatch(new PlatformIdentityUpdateAllowDecision(Allow::allowed('update', 'Allowed to update by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fixedFields(?PlatformIdentityRef $ref = null): array
    {
        $this->logDebug("Check fixed fields for update usecase for Platform identity");
        $span = $this->startSpan("Check fixed fields for update usecase for Platform identity");
        try {
            return $this->visibility->fieldsToFix($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function update(string $uid, PlatformIdentityUpdateParams $params): PlatformIdentityUpdateResult
    {
        $this->logDebug("Run update usecase for Platform identity");
        $span = $this->startSpan("Run update usecase for Platform identity");
        try {
            $ref = new PlatformIdentityRef($uid);
            $allow = $this->allowUpdate($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to update Platform identity');
            }
            if (!$original = $this->visibility->retrieveVisibleForUpdate($ref)) {
                throw new NotFoundException($uid);
            }
            $this->dispatcher->dispatch(new PlatformIdentityUpdateCheck($params, $original));
            $enriched = $this->dispatcher->dispatch(new PlatformIdentityUpdateEnrich($params, $original, $params->toAttributes()));
            $attributes = $enriched->getResult();
            $input = $this->visibility->copyWithFixed($attributes);
            $modified = $original->update($input);
            $result = $this->writer->update($original, $modified);
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new PlatformIdentityUpdateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
